// -- Tunable constants --------------------------------------------------------
// Base time window: folios accessed within this window are "recently used"
#define RECENT_ACCESS_NS_BASE    50000000ULL    // 50 ms (tightened from 100 ms)
// Time window: network session considered active if packet within this window
#define NET_IDLE_TIMEOUT_NS      5000000000ULL  // 5 s
// Working set window: protect folios accessed within this window during active session
#define WORKING_SET_NS_BASE      500000000ULL   // 500 ms (tightened from 1 s)
// Access count threshold: folios with >= this many accesses are "hot"
#define HOT_ACCESS_THRESHOLD     3
// Promoted tier threshold: folios with >= this many accesses (after decay) are "promoted"
#define PROMOTED_THRESHOLD       5
// Protection window for promoted folios (longer than base)
#define PROMOTED_PROTECTION_NS   200000000ULL   // 200 ms
// Burst detection: inter-arrival time threshold (us) - below this is a burst
#define BURST_THRESHOLD_US       5000ULL        // 5 ms (tightened from 10 ms)
// RTT threshold for high-latency networks (us)
#define HIGH_RTT_THRESHOLD_US    50000ULL       // 50 ms
// Congestion threshold: if retrans_out > 0 or lost > 0, network is congested
#define CONGESTION_THRESHOLD     1
// Decay window: decay access count for folios older than this
#define ACCESS_DECAY_WINDOW_NS   500000000ULL   // 500 ms (faster decay for scan workloads)
// Decay factor: divide access_count by this when page is old
#define ACCESS_DECAY_DIVISOR     2
// Scoring constants for frequency-recency combined metric
#define SCORE_PER_ACCESS         10             // weight per effective access
#define SCORE_RECENCY_MAX        100            // max recency bonus
#define SCORE_EVICTION_THRESHOLD 50             // evict if score < this

// -- Helper: compute time-decayed access count --------------------------------
static __always_inline u32 get_decayed_access_count(struct net_folio_metadata *meta, u64 now)
{
    u64 age = (now > meta->last_access_ts) ? (now - meta->last_access_ts) : 0;

    // If folio is older than decay window, reduce its access count
    // This prevents old accesses from keeping pages classified as "hot"
    if (age > ACCESS_DECAY_WINDOW_NS) {
        // Decay: divide by divisor, but keep at least 1
        u32 decayed = (meta->access_count / ACCESS_DECAY_DIVISOR);
        if (decayed < 1) decayed = 1;
        return decayed;
    }

    return meta->access_count;
}

// -- Helper: compute combined frequency-recency score --------------------------
static __always_inline u32 get_folio_score(struct net_folio_metadata *meta, u64 now)
{
    u32 effective_accesses = get_decayed_access_count(meta, now);
    u64 age = (now > meta->last_access_ts) ? (now - meta->last_access_ts) : 0;

    // Recency bonus: linear decay from 100 to 0 over RECENT_ACCESS_NS
    u32 recency_bonus = 0;
    if (age < RECENT_ACCESS_NS_BASE) {
        // recency_bonus = 100 * (1 - age/RECENT_ACCESS_NS)
        recency_bonus = (SCORE_RECENCY_MAX * (RECENT_ACCESS_NS_BASE - age)) / RECENT_ACCESS_NS_BASE;
    }

    // Combined score: frequency contribution + recency bonus
    u32 score = (effective_accesses * SCORE_PER_ACCESS) + recency_bonus;

    return score;
}

// -- Helper: compute adaptive thresholds based on network state ---------------
static __always_inline u64 get_adaptive_recent_access_ns(void)
{
    // Base threshold (tightened)
    u64 threshold = RECENT_ACCESS_NS_BASE;

    // Detect network congestion
    bool has_loss = (net_lost > 0);
    bool has_retrans = (net_retrans_out > 0);
    bool is_congested = has_loss || has_retrans;

    // High RTT means cache misses are expensive - protect more pages
    bool high_rtt = (net_srtt_us > HIGH_RTT_THRESHOLD_US);

    // If congested or high RTT, shrink the window to focus on hottest pages
    if (is_congested || high_rtt) {
        threshold = threshold / 2;  // 25 ms
    }

    return threshold;
}

static __always_inline u64 get_adaptive_working_set_ns(void)
{
    u64 threshold = WORKING_SET_NS_BASE;

    // Detect burst: if inter-arrival time is small, we're in a burst
    u64 inter_arrival = (last_packet_ts > net_prev_packet_ts) ?
                        (last_packet_ts - net_prev_packet_ts) : 0;

    // Convert to microseconds for comparison (avoid overflow)
    u64 inter_arrival_us = inter_arrival / 1000;

    // During burst (small inter-arrival), expand working set protection
    if (inter_arrival_us > 0 && inter_arrival_us < BURST_THRESHOLD_US) {
        threshold = threshold * 2;  // 1 s during bursts
    }

    return threshold;
}

// -- Eviction iteration callback ----------------------------------------------
// Called for each folio during eviction scan.
// Return CACHE_EXT_EVICT_NODE to evict, CACHE_EXT_CONTINUE_ITER to keep.
static int bpf_evict_cb(int idx, struct cache_ext_list_node *node)
{
    u64 now = bpf_ktime_get_ns();
    u64 key = (u64)node->folio;

    struct net_folio_metadata *meta =
        bpf_map_lookup_elem(&folio_metadata_map, &key);

    // No metadata → unknown folio → evict
    if (!meta)
        return CACHE_EXT_EVICT_NODE;

    // Skip dirty / under-writeback folios (kernel can't evict them anyway)
    if (folio_test_dirty(node->folio) || folio_test_writeback(node->folio))
        return CACHE_EXT_CONTINUE_ITER;

    // -- Network-aware adaptive heuristics with scoring -----------------------

    u64 recent_access_ns = get_adaptive_recent_access_ns();
    u64 working_set_ns = get_adaptive_working_set_ns();

    bool session_active = (now - last_packet_ts) < NET_IDLE_TIMEOUT_NS;
    bool recently_used  = (now - meta->last_access_ts) < recent_access_ns;
    bool in_working_set = (now - meta->last_access_ts) < working_set_ns;

    // Apply time-weighted decay to access count
    u32 effective_access_count = get_decayed_access_count(meta, now);
    bool is_hot         = (effective_access_count >= HOT_ACCESS_THRESHOLD);
    bool very_hot       = (effective_access_count >= HOT_ACCESS_THRESHOLD + 2);
    bool is_promoted    = (meta->access_tier == 3);  // tier 3 = promoted

    // Detect network congestion
    bool is_congested = (net_lost > 0) || (net_retrans_out > 0);

    // Compute frequency-recency score for continuous ranking
    u32 folio_score = get_folio_score(meta, now);

    // Protect promoted folios with extended window, even when session not active
    // This creates a top-tier protection for truly critical pages
    if (is_promoted && (now - meta->last_access_ts) < PROMOTED_PROTECTION_NS)
        return CACHE_EXT_CONTINUE_ITER;

    // Protect very hot folios aggressively during active session
    if (very_hot && session_active)
        return CACHE_EXT_CONTINUE_ITER;

    // Protect hot folios (many accesses) that were recently touched
    if (is_hot && recently_used)
        return CACHE_EXT_CONTINUE_ITER;

    // During an active network session, protect the working set
    if (session_active && in_working_set)
        return CACHE_EXT_CONTINUE_ITER;

    // During network congestion, be more aggressive about protecting hot pages
    if (is_congested && is_hot && (now - meta->last_access_ts) < working_set_ns)
        return CACHE_EXT_CONTINUE_ITER;

    // Protect any recently accessed folio
    if (recently_used)
        return CACHE_EXT_CONTINUE_ITER;

    // Aggressive eviction based on score: evict low-scoring folios (weak frequency + recency)
    // This particularly targets single-access pages that aren't recent (common in scans)
    if (folio_score < SCORE_EVICTION_THRESHOLD)
        return CACHE_EXT_EVICT_NODE;

    // Everything else → evict
    return CACHE_EXT_EVICT_NODE;
}

